/**
 * Mission planning for agricultural fleets: converts a MissionItem into fleet tasks (one work path per row side, or per
 * alley for centred implements). What happens on the rows is modelled by the process models in ./process (registered
 * on import, so every FleetManager executes them): picking time per fruit with base stops, fruit removed at pick time,
 * spray dose and tank refills, coverage, per-plant workloads, scouting observations, bins and deliveries.
 * Arm programs for a mounted robot are generated by ./harvest (re-exported here).
 */
import { Station, ItemType } from '../core/items/item';
import { Program } from '../core/items/program';
import { FieldItem, CropRow, MissionItem, MissionType } from './items';
import { fruitWorldPositions } from './orchard';
import { FleetManager, FleetTask, TaskType } from '../fleet/fleet';
import { MobileRobot } from '../mobile/items';
import { orderRowsNearest, headlandTurns } from '../mobile/planner';
import { minTurnRadius } from '../mobile/controller';
import { transl, add, scale } from '../core/math/pose';
import { armOf, armMount, armReach } from './harvest';
import './process';
import './collision_world';

export { generateHarvestProgram, bindHarvestEvents, matchDetections, armReach, fruitByRef, fruitTargets } from './harvest';
export type { HarvestProgramOptions } from './harvest';

const TASK_OF: Record<MissionType, TaskType> = { harvest: 'harvest', spray: 'spray', mow: 'mow', prune: 'prune', scout: 'scout', transport: 'transport', pollinate: 'pollinate', weed: 'weed', thin: 'thin', irrigate: 'irrigate' };
/** Capability a robot needs (thinning uses the picking arm). */
const CAP_OF: Record<MissionType, string> = { harvest: 'harvest', spray: 'spray', mow: 'mow', prune: 'prune', scout: 'scout', transport: 'transport', pollinate: 'pollinate', weed: 'weed', thin: 'harvest', irrigate: 'irrigate' };

export interface MissionPlan {
  tasks: FleetTask[];
  totalPathLength: number;
  estimatedHours: number;
  rows: number;
  fruitTargets?: number;
  /** Planner warnings (headland too short for an Ackermann robot, …). */
  warnings: string[];
}

/**
 * Plan a mission: one fleet task per row side (or per row for centred implements like mowers). Work paths are travel
 * lines beside the row in the station frame; for arm missions the direction is chosen so the arm faces the row (and
 * re-oriented for the robot that gets the task). Picking time is not folded into a slow work speed: the base drives
 * between stops at the work speed and stands still while the arm picks (secondsPerFruit each).
 */
export function planMission(station: Station, mission: MissionItem, fleet: FleetManager): MissionPlan {
  const field = mission.fieldId ? (station.findById(mission.fieldId) as FieldItem | null) : station.itemsOfType<FieldItem>(ItemType.FIELD)[0];
  if (!field) throw new Error('Mission has no field');
  const rows = (mission.rowIds.length ? mission.rowIds.map((id) => station.findById(id)).filter((r): r is CropRow => r instanceof CropRow) : field.rows());
  const abs = field.poseAbs();
  const toWorld = (p: number[]) => [abs[0] * p[0] + abs[4] * p[1] + abs[12], abs[1] * p[0] + abs[5] * p[1] + abs[13]];
  const s = mission.settings;
  const type = mission.missionType;
  const centred = type === 'mow' || type === 'weed' || type === 'irrigate' || type === 'scout';
  const armMission = type === 'harvest' || type === 'thin' || type === 'prune' || type === 'pollinate';
  const sideOffset = centred ? field.crop.rowSpacing / 2 : (s.sideOffset ?? field.crop.rowSpacing / 2);
  const workSpeed = s.workSpeed ?? 500;
  const spf = s.secondsPerFruit ?? (type === 'thin' ? 2 : 6);
  const warnings: string[] = [];
  const lines: Array<{ row: CropRow; side: 1 | -1; start: number[]; end: number[] }> = [];
  for (const r of rows) {
    if (centred) lines.push({ row: r, side: 1, ...r.travelLine(sideOffset) });
    else {
      lines.push({ row: r, side: 1, ...r.travelLine(sideOffset) });
      if (s.bothSides !== false) lines.push({ row: r, side: -1, ...r.travelLine(-sideOffset) });
    }
  }
  const robots = fleet.robots().filter((r) => r.capabilities.includes(CAP_OF[type]));
  const allRobots = fleet.robots();
  const from = (robots[0] ?? allRobots[0]) ? [(robots[0] ?? allRobots[0]).state.x, (robots[0] ?? allRobots[0]).state.y] : toWorld(rows[0]?.start ?? [0, 0]);
  const order = orderRowsNearest(lines.map((l) => ({ start: toWorld(l.start), end: toWorld(l.end) })), from);
  // arm side of the carriers (all capable robots normally share the layout; re-oriented per robot on assignment)
  const arm = armMission ? robots.map((r) => armOf(r)).find((a) => a) ?? null : null;
  const armSide = arm ? armMount(arm).side : 0;
  const tasks: FleetTask[] = [];
  let total = 0;
  let fruitTargets = 0;
  order.forEach((li, k) => {
    const l = lines[li];
    const a = toWorld(l.start), b = toWorld(l.end);
    let path: number[][];
    if (armSide) path = -l.side * armSide > 0 ? [a, b] : [b, a];
    else path = k % 2 === 1 ? [b, a] : [a, b]; // alternate to shorten headland turns
    const ripe = type === 'harvest' ? fruitWorldPositions(l.row).filter((f) => f.side === l.side).length : 0;
    fruitTargets += ripe;
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]);
    total += len;
    const t = fleet.addTask({
      type: TASK_OF[type],
      location: [path[0][0], path[0][1]],
      goalHeading: Math.atan2(path[1][1] - path[0][1], path[1][0] - path[0][0]) * 180 / Math.PI,
      workPath: path,
      workSpeed,
      priority: s.priority ?? 1,
      requiredCapabilities: [CAP_OF[type]],
      // traffic segment = the alley the robot drives in (shared by the two rows bordering it)
      segments: [centred ? `${field.id}:alley${l.row.index}` : `${field.id}:alley${l.row.index + (l.side > 0 ? 0 : -1)}`],
      meta: { missionId: mission.id, rowId: l.row.id, side: centred ? 0 : l.side, fruit: ripe, fruitKg: fruitMassKg(field.crop.fruitDiameter), swathM: (centred ? field.crop.rowSpacing : sideOffset) / 1000, process: TASK_OF[type], expectedWorkSeconds: ripe * spf },
    });
    tasks.push(t);
  });
  // headland check for car-like robots: can they turn from one alley into the next within the headland?
  for (const r of robots.filter((x) => x.kin.drive === 'ackermann')) {
    if (rows.length < 2) break;
    const r0 = rows[0], r1 = rows[1];
    const e0 = toWorld(r0.travelLine(sideOffset).end), s1 = toWorld(r1.travelLine(sideOffset).end);
    const d = r0.direction();
    const th = Math.atan2(abs[1] * d[0] + abs[5] * d[1], abs[0] * d[0] + abs[4] * d[1]) * 180 / Math.PI;
    const turns = headlandTurns({ x: e0[0], y: e0[1], theta: th }, { x: s1[0], y: s1[1], theta: th + 180 }, minTurnRadius(r.kin) * 1.15, [r.kin.footprint[0], r.kin.footprint[1]]);
    const best = turns.reduce((p, q) => (q.depth < p.depth ? q : p), turns[0]);
    if (best && best.depth > field.crop.headland) warnings.push(`${r.name}: a ${best.kind} turn needs ${(best.depth / 1000).toFixed(1)} m of headland, the field has ${(field.crop.headland / 1000).toFixed(1)} m`);
  }
  if (armMission && robots.length && !arm) warnings.push('No arm mounted on the capable robots: picking time is simulated without reach limits');
  mission.taskIds = tasks.map((t) => t.id);
  mission.status = 'planned';
  mission.warnings = warnings;
  const n = Math.max(1, robots.length || allRobots.length);
  const est = (total / workSpeed + fruitTargets * spf) / n / 3600;
  return { tasks, totalPathLength: total, estimatedHours: est, rows: rows.length, fruitTargets, warnings };
}

/** Approximate fruit mass from diameter (sphere, density ~0.9 g/cm³). */
export function fruitMassKg(diameterMm: number): number {
  const r = diameterMm / 20; // cm
  return (4 / 3) * Math.PI * r * r * r * 0.9 / 1000;
}

/**
 * Legacy hook: deplete all ripe fruit of a row side when a harvest task without a process model finishes. The harvest
 * process model (registered on import) supersedes it; kept for custom managers that disable process models.
 */
export function installHarvestHook(station: Station, fleet: FleetManager): void {
  fleet.onHarvestDone = (task) => {
    const row = task.meta?.rowId ? (station.findById(task.meta.rowId) as CropRow | null) : null;
    if (!row) return { fruit: 0, kg: 0 };
    let n = 0;
    const side = task.meta?.side ?? 0;
    for (const p of row.plants) for (const f of p.fruit) {
      if (f.picked || f.ripe < 0.5) continue;
      if (side && (f.p[1] >= 0 ? 1 : -1) !== side) continue;
      f.picked = true;
      n++;
    }
    row.notify('plants');
    return { fruit: n, kg: n * (task.meta?.fruitKg ?? 0.18) };
  };
}

/** Update mission progress from the fleet task states. */
export function updateMissionProgress(mission: MissionItem, fleet: FleetManager): void {
  const tasks = fleet.fleet.tasks.filter((t) => mission.taskIds.includes(t.id) || t.meta?.missionId === mission.id);
  if (!tasks.length) return;
  const done = tasks.filter((t) => t.status === 'done').length;
  mission.progress = done / tasks.length;
  if (mission.progress >= 1) mission.status = 'done';
  else if (tasks.some((t) => t.status !== 'pending')) mission.status = 'running';
}

/** Spray mission helper: emit a program for a boom sprayer mounted on a mobile robot (signals on/off along rows). */
export function generateSprayProgram(station: Station, robot: MobileRobot, rows: CropRow[], sideOffset: number, speed = 800): Program {
  const prog = station.addChild(new Program(`Spray ${robot.name}`));
  prog.setRobot(robot);
  const field = rows[0]?.parent as FieldItem | undefined;
  const abs = field ? field.poseAbs() : transl(0, 0, 0);
  const toWorld = (p: number[]) => [abs[0] * p[0] + abs[4] * p[1] + abs[12], abs[1] * p[0] + abs[5] * p[1] + abs[13]];
  rows.forEach((r, i) => {
    const line = r.travelLine(i % 2 === 0 ? sideOffset : -sideOffset);
    const a = toWorld(i % 2 === 0 ? line.start : line.end), b = toWorld(i % 2 === 0 ? line.end : line.start);
    const th = Math.atan2(b[1] - a[1], b[0] - a[0]) * 180 / Math.PI;
    prog.navigateTo(a[0], a[1], th, { speed, label: `${r.name} entry` });
    prog.addInstruction({ kind: 'signal', signal: 'spray', value: true, wait: false });
    prog.navigateTo(b[0], b[1], th, { speed, label: `${r.name} exit` });
    prog.addInstruction({ kind: 'signal', signal: 'spray', value: false, wait: false });
  });
  return prog;
}

export { add, scale, armReach as realReach };
